Q: read message and attachment name of the same mail using javamail A: <p>Unfortunately, It's a little bit more complicated than just iterating through a list, because the MimeMessage structure is a tree and bodies/attachments can occur on multiple levels. So you'll have to recursively traverse the structure.</p>
<p><strong>Jakarta Mail / Angus solution</strong></p>
<pre class="lang-java prettyprint-override"><code>static void printPart(Part part) throws MessagingException, IOException {
    String disposition = part.getDisposition();
    String encodedName = part.getFileName();

    boolean resource =
            Part.ATTACHMENT.equalsIgnoreCase(disposition)
            || Part.INLINE.equalsIgnoreCase(disposition)
            || encodedName != null;

    if (resource) {
        String name = encodedName == null
                ? &quot;(unnamed)&quot;
                : MimeUtility.decodeText(encodedName);

        String kind = Part.INLINE.equalsIgnoreCase(disposition)
                ? &quot;Inline resource&quot;
                : &quot;Attachment&quot;;

        System.out.println(kind + &quot;: &quot; + name);

        // To consume the attachment:
        // try (InputStream in = part.getInputStream()) { ... }

        return;
    }

    if (part.isMimeType(&quot;text/plain&quot;)) {
        System.out.println(&quot;Plain content: &quot; + part.getContent());
    } else if (part.isMimeType(&quot;text/html&quot;)) {
        System.out.println(&quot;HTML content: &quot; + part.getContent());
    } else if (part.isMimeType(&quot;multipart/*&quot;)) {
        Multipart multipart = (Multipart) part.getContent();

        for (int i = 0; i &lt; multipart.getCount(); i++) {
            printPart(multipart.getBodyPart(i));
        }
    } else if (part.isMimeType(&quot;message/rfc822&quot;)) {
        Object nested = part.getContent();

        if (nested instanceof Part) {
            printPart((Part) nested);
        }
    }
}
</code></pre>
<p>To use this:</p>
<pre class="lang-java prettyprint-override"><code>for (Message message : folder.getMessages()) {
    System.out.println(&quot;Subject: &quot; + message.getSubject());
    printPart(message);
}
</code></pre>
<p>Btw, use <code>Part.getFileName()</code> for the attachment filename as <code>DataHandler.getName()</code> doesn't always have to be the MIME filename. And body ofter occurs as text/plain, text/html or both, so pick one probably.</p>
<p>There's a much simpler way to do this, however. <a href="https://simplejavamail.org/" rel="nofollow noreferrer">Simple Java Mail</a> (open source, I maintain it) handles this recursive structure traversal under the hood. Behold:</p>
<pre class="lang-java prettyprint-override"><code>for (Message message : folder.getMessages()) {
    MimeMessage mimeMessage = (MimeMessage) message;

    // false: retrieve attachment metadata without eagerly copying payloads
    Email email =
            EmailConverter.mimeMessageToEmail(mimeMessage, null, false);

    String body = email.getPlainText() != null
            ? email.getPlainText()
            : email.getHTMLText();

    System.out.println(&quot;Content: &quot; + body);

    for (AttachmentResource attachment : email.getAttachments()) {
        System.out.println(&quot;Attachment: &quot; + attachment.getName());
    }

    for (AttachmentResource embedded : email.getEmbeddedImages()) {
        System.out.println(&quot;Embedded resource: &quot; + embedded.getName());
    }
}
</code></pre>

Q: How to do a tls handshake with &quot;api.steampowered.com&quot; using boost asio? A: <p>You need <a href="https://en.wikipedia.org/wiki/Server_Name_Indication" rel="nofollow noreferrer">SNI</a>, just like you added on the <code>openssl s_connect</code>:</p>
<blockquote>
<p>note the various other simplifications you might like to review</p>
</blockquote>
<p><a href="https://godbolt.org/z/nETd7qax9" rel="nofollow noreferrer">Live On Compiler Explorer</a></p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;boost/asio.hpp&gt;
#include &lt;boost/asio/ssl/context.hpp&gt;
#include &lt;boost/beast.hpp&gt;
#include &lt;boost/beast/ssl.hpp&gt;
#include &lt;print&gt;
namespace asio = boost::asio;
// namespace beast = boost::beast;
namespace ssl = asio::ssl;
using asio::ip::tcp;

boost::asio::awaitable&lt;void&gt; run_ssl() {

    auto         ex = co_await asio::this_coro::executor;
    ssl::context ctx(ssl::context::tls_client);
    auto         conn = boost::beast::ssl_stream&lt;boost::beast::tcp_stream&gt;{ex, ctx};

    get_lowest_layer(conn).expires_never();

    std::string host = &quot;api.steampowered.com&quot;;
    std::string port = &quot;443&quot;;

    if (!::SSL_set_tlsext_host_name(conn.native_handle(), host.c_str()))
        throw boost::system::system_error(static_cast&lt;int&gt;(::ERR_get_error()),
                                          asio::error::get_ssl_category());

    tcp::resolver resolver(ex);

    auto results = co_await resolver.async_resolve(host, port);

    co_await get_lowest_layer(conn).async_connect(results);
    co_await conn.async_handshake(ssl::stream_base::client);
}

int main() {
    auto ioc = boost::asio::io_context{1};

    asio::co_spawn(ioc, run_ssl(), [](auto ep) {
        if (ep) {
            try {
                std::rethrow_exception(ep);
            } catch (std::exception const&amp; e) {
                std::print(&quot;exception: {}&quot;, e.what());
            }
        }
    });

    ioc.run();
}
</code></pre>
